/* ==== data-bigcode.js ==== */

/* ============================================================
   课程十一：长代码精读训练
   4 个 100~200 行的真实规模程序：先读懂，再动手改造
   目标是解决"短代码会写、长代码看不懂"的问题
   ============================================================ */
window.COURSES = window.COURSES || [];
window.COURSES.push({
  id: "bigcode",
  badge: "精读",
  badgeCls: "cb-bigcode",
  title: "长代码精读训练",
  brief: "100~200 行真实代码，读懂再改",
  desc: "环形缓冲区、协议解析状态机、线程池、内存池四个真实规模程序。每个都给出完整实现与阅读指引，配读代码题与改造任务。",
  goal: "能读懂 100~200 行的真实工程代码，说出每段的设计意图、边界处理与潜在缺陷。",
  roles: ["mcu", "rtos", "linux", "drv", "iot"],
  dep: ["c", "camp"],
  chapters: [

  /* ---------------- 第 1 章 ---------------- */
  {
    id: "bc1",
    title: "长代码一：环形缓冲区",
    brief: "嵌入式最常见的通信缓冲（约 130 行）",
    points: [
      { t: "阅读任务：先搞清三个问题",
        h: "<p>看代码前，先带着这三个问题往下读，读完能回答就说明读懂了：</p><ol><li><b>索引怎么取模？</b>为什么用 <code>&amp; (SIZE-1)</code> 而不是 <code>% SIZE</code>？</li><li><b>volatile 出现在哪里？</b>既然中断和主循环都在访问，为什么不需要加锁？</li><li><b>函数返回值的契约是什么？</b>0 / -1 / 实际长度分别代表什么？</li></ol><p>读代码的通用方法：先看头文件（接口 = 契约），再看实现（细节），最后看调用示例（用法）。</p>" },
      { t: "完整实现（接口 + 实现）",
        h: "<p>这是单生产者单消费者（SPSC）环形缓冲区，串口收发、日志缓冲、任务队列都能用它。注意每处注释标出的<b>设计意图</b>，那才是面试要问的东西。</p>",
        code: "#include <stdint.h>\n#include <string.h>\n\n#define RB_SIZE 256                    /* 必须是 2 的幂：用掩码取模更快 */\n\ntypedef struct {\n    volatile uint32_t w;               /* 写索引：只有生产者（中断）修改 */\n    volatile uint32_t r;               /* 读索引：只有消费者（主循环）修改 */\n    uint8_t buf[RB_SIZE];\n} ringbuf_t;\n\nstatic inline uint32_t rb_mask(uint32_t v)\n{\n    return v & (RB_SIZE - 1);          /* 等价于 % RB_SIZE，但不用除法 */\n}\n\n/* 可读字节数 */\nstatic inline uint32_t rb_available(const ringbuf_t *rb)\n{\n    uint32_t w = rb->w;                /* 先读 w 再读 r：避免读到\"偏大\"的中间态 */\n    uint32_t r = rb->r;\n    return (w - r) & (RB_SIZE - 1);    /* 无符号减法天然处理绕回 */\n}\n\n/* 还剩多少空间（牺牲一格，所以最大可用是 SIZE-1） */\nstatic inline uint32_t rb_space(const ringbuf_t *rb)\n{\n    return (RB_SIZE - 1) - rb_available(rb);\n}\n\n/* 放入一个字节：满则返回 -1（不阻塞，适合中断里调用） */\nint rb_put(ringbuf_t *rb, uint8_t b)\n{\n    uint32_t next = rb_mask(rb->w + 1);\n    if (next == rb->r)\n        return -1;                     /* 判满：下一个位置撞上读指针 */\n    rb->buf[rb->w] = b;                /* 先写数据 */\n    rb->w = next;                      /* 后更新索引：保证消费者不会看到未写入的数据 */\n    return 0;\n}\n\nint rb_get(ringbuf_t *rb, uint8_t *b)\n{\n    if (rb->r == rb->w)\n        return -1;                     /* 判空：两指针相等 */\n    *b = rb->buf[rb->r];\n    rb->r = rb_mask(rb->r + 1);\n    return 0;\n}\n\n/* 批量写：可能只写进去一部分，返回实际写入的字节数 */\nint rb_write(ringbuf_t *rb, const uint8_t *data, int len)\n{\n    int n = 0;\n    uint32_t space = rb_space(rb);\n    if ((uint32_t)len > space)\n        len = (int)space;              /* 截断到可用空间，绝不越界 */\n\n    while (n < len) {\n        uint32_t chunk = RB_SIZE - rb->w;    /* 到缓冲区末尾的连续空间 */\n        if (chunk > (uint32_t)(len - n))\n            chunk = (uint32_t)(len - n);\n        memcpy(&rb->buf[rb->w], data + n, chunk);\n        rb->w = rb_mask(rb->w + chunk);      /* 绕回 */\n        n += (int)chunk;\n    }\n    return n;\n}\n\n/* 批量读：与 rb_write 对称 */\nint rb_read(ringbuf_t *rb, uint8_t *data, int len)\n{\n    int n = 0;\n    uint32_t avail = rb_available(rb);\n    if ((uint32_t)len > avail)\n        len = (int)avail;\n\n    while (n < len) {\n        uint32_t chunk = RB_SIZE - rb->r;\n        if (chunk > (uint32_t)(len - n))\n            chunk = (uint32_t)(len - n);\n        memcpy(data + n, &rb->buf[rb->r], chunk);\n        rb->r = rb_mask(rb->r + chunk);\n        n += (int)chunk;\n    }\n    return n;\n}" },
      { t: "调用示例：中断生产 + 主循环消费",
        h: "<p>这才是它的实战形态：中断里只负责快速塞进缓冲区，主循环里慢慢解析。这样中断时间最短，系统实时性最好。</p>",
        code: "static ringbuf_t g_rx_rb;   /* 串口接收缓冲 */\n\n/* ---------- 生产者：中断上下文，必须极快、绝不阻塞 ---------- */\nvoid UART_IRQHandler(void)\n{\n    uint8_t ch;\n    while (uart_rx_ready()) {\n        ch = uart_read_reg();\n        if (rb_put(&g_rx_rb, ch) != 0) {\n            g_rx_drop++;            /* 满了就丢弃并计数，不阻塞中断 */\n        }\n    }\n}\n\n/* ---------- 消费者：主循环上下文，可以慢慢处理 ---------- */\nvoid main_loop(void)\n{\n    uint8_t tmp[64];\n    int n = rb_read(&g_rx_rb, tmp, sizeof(tmp));\n    if (n > 0)\n        protocol_feed(&g_parser, tmp, n);   /* 交给协议解析状态机（下一章） */\n}" },
      { t: "读完自查（能答上来就算过关）",
        h: "<ul><li>为什么判满要牺牲一个格子？不牺牲会出现什么问题？</li><li>为什么 <code>rb->w</code> 必须在数据写入之后才更新？反过来会怎样？</li><li>这里没有用锁，为什么是安全的？（提示：单写者 + 索引是机器字长）</li><li><code>rb_write</code> 返回小于 len 时，调用者应该怎么处理？</li></ul>" }
    ],
    quiz: [
      { type: "blank", q: "读程序算数：设 RB_SIZE=256，当前 w=5、r=250（都还没绕完一圈），rb_available() 返回多少字节？",
        code: "uint32_t w = rb->w;   /* 5 */\nuint32_t r = rb->r;   /* 250 */\nreturn (w - r) & (RB_SIZE - 1);",
        blanks: [{ acc: ["11"] }],
        exp: "5-250 在无符号运算里回绕成一个大数，(5-250)&255 = 11。这正是它优雅的地方：无需 if 判断绕回，无符号减法配合掩码自动处理。" },
      { type: "single", q: "判满时故意少用一个格子（(w+1)&mask == r 算满），根本原因是？",
        opts: ["省内存", "若不牺牲一格，就无法区分\"空\"与\"满\"——两种情况都是 w == r", "让取模更快", "防止 volatile 失效"], ans: 1,
        exp: "w==r 既可能表示空、也可能表示装满了。牺牲一格（或用计数器/序列号）就能区分。这是环形缓冲区的经典设计取舍。" },
      { type: "blank", q: "补全 rb_put 里保证正确性的关键顺序：",
        code: "rb->buf[rb->w] = b;   /* 先写数据 */\n{{0}};                 /* 后更新索引 */",
        blanks: [{ acc: ["rb->w=next", "rb->w = next"] }],
        exp: "先写数据、后更新写索引。反过来的话，消费者可能看到\"索引已前进但数据还没写\"的状态，读到脏数据——这类顺序问题在并发代码里是最隐蔽的 bug。" },
      { type: "judge", q: "这个实现没有加锁，但因为是\"单生产者 + 单消费者 + 索引各自只有一个写者\"，所以是安全的（volatile 保证可见性，机器字长的读写具备原子性）。", ans: true,
        exp: "关键前提有三个：① 只有一方写 w、只有一方写 r；② 索引是 32 位，在目标平台上读写不会撕裂；③ volatile 禁止编译器把它缓存进寄存器。缺任何一条就得上锁或原子操作。" },
      { type: "single", q: "rb_write() 返回 40，而调用时 len 是 100，说明？",
        opts: ["出错了，应该返回 -1", "缓冲区空间不足，只写入了 40 字节，剩下 60 字节需要调用者稍后重试", "缓冲区已满且已丢弃数据", "返回值永远是 len"], ans: 1,
        exp: "这是\"部分写入\"语义：返回实际写入量，由调用者决定重试或丢弃。TCP 的 write、fwrite 也有类似语义，看到返回值就必须处理。" },
      { type: "code", q: "改造任务一：给环形缓冲区加两个实用函数——rb_peek()（查看下一个字节但不消费）和 rb_reset()（清空缓冲区）。注意 reset 在并发场景下要怎么做才安全，并在注释里说明。",
        hint: "<p>peek 只读不移动 r；reset 的危险在于消费者可能正在读——正确做法是只由消费者侧调用，或先关中断再重置（两者选一种并注明前提）。</p>",
        sol: "/* 查看下一个可读字节但不消费它：返回 0 成功，-1 表示空 */\nint rb_peek(const ringbuf_t *rb, uint8_t *b)\n{\n    if (rb->r == rb->w) return -1;\n    *b = rb->buf[rb->r];\n    return 0;\n}\n\n/* 清空缓冲区。\n * 调用前提：必须在\"消费者侧\"调用，且此时生产者（中断）不能同时写入。\n * 最简单可靠的写法是关中断后重置：\n */\nvoid rb_reset(ringbuf_t *rb)\n{\n    unsigned long flags = irq_save();   /* 关中断，避免中断里 rb_put 与这里竞争 */\n    rb->r = 0;\n    rb->w = 0;\n    irq_restore(flags);\n}\n\n/* 说明：若不能关中断，则只重置读指针（丢弃未处理数据）：\n *     rb->r = rb->w;\n * 这是\"消费方主动丢弃\"的常见做法，等价于清空但不动生产者索引。\n */",
        exp: "重点不是这两行代码，而是\"重置共享状态必须有并发前提\"这个意识。写驱动的同学都知道：凡是改共享变量，先问自己\"此刻有没有别人在访问\"。" },
      { type: "code", q: "改造任务二：实现 rb_read_line(rb, buf, size)，从缓冲区里取出一整行（以 '\\n' 结尾）。要求：没有完整行时返回 0（表示数据不足、等待更多数据），成功时返回取出的字节数（含换行、不含结尾 '\\0'），超长行返回 -1。",
        hint: "<p>思路：先扫描一遍看有没有 '\\n'（用 rb_peek 或直接访问 buf 而不移动 r）；确认有完整行再逐字节 rb_get 拷出。找不到换行就直接返回 0，千万别先消费再判断。</p>",
        sol: "int rb_read_line(ringbuf_t *rb, char *buf, int size)\n{\n    if (rb == NULL || buf == NULL || size <= 1) return -1;\n\n    /* 1. 先探测：有没有完整的行？不移动读指针 */\n    uint32_t avail = rb_available(rb);\n    uint32_t idx = rb->r;\n    int found = -1;\n    for (uint32_t i = 0; i < avail; i++) {\n        if (rb->buf[idx] == '\\n') { found = (int)i; break; }\n        idx = rb_mask(idx + 1);\n    }\n    if (found < 0) return 0;                 /* 数据不足，等下次 */\n    if (found + 1 >= size) {                 /* 用户缓冲太小 */\n        return -1;\n    }\n\n    /* 2. 确认有完整行，再消费出来 */\n    int n = 0;\n    uint8_t b;\n    while (rb_get(rb, &b) == 0) {\n        buf[n++] = (char)b;\n        if (b == '\\n') break;\n    }\n    buf[n] = '\\0';\n    return n;\n}",
        exp: "核心是\"探测与消费分离\"：先看不消费，确认完整再取。很多新手写成\"边读边找换行，找不到就把数据吞了\"，结果半个包被丢掉，解析永远失败。这个思路和 TCP 收包一模一样。" }
    ]
  },

  /* ---------------- 第 2 章 ---------------- */
  {
    id: "bc2",
    title: "长代码二：协议解析状态机",
    brief: "粘包半包的正确处理方式（约 150 行）",
    points: [
      { t: "阅读任务：带着问题读",
        h: "<ol><li>一次 <code>parser_feed</code> 只收到半个命令，状态存在哪里？下次怎么接着解析？</li><li>行太长时为什么不直接返回错误，而是标记 <code>overflow</code> 继续吞字节？</li><li>命令分发为什么用\"表\"而不是一串 if-else？</li></ol>" },
      { t: "完整实现（头文件 + 实现）",
        h: "<p>这个解析器与你的点餐项目协议同源（行协议 + 命令名 + 参数），可直接套用。注意命令表用函数指针：新增命令只加一行。</p>",
        code: "#ifndef PROTO_H\n#define PROTO_H\n\n#include <stdint.h>\n\n#define LINE_MAX 128\n#define CMD_MAX  8\n\ntypedef struct {\n    const char *name;\n    void (*fn)(const char *args);      /* 命令处理函数 */\n} cmd_entry_t;\n\ntypedef struct {\n    char line[LINE_MAX];\n    int  len;                          /* 当前已缓存字节数 */\n    int  overflow;                     /* 本行是否已超长 */\n    int  frames;                       /* 成功解析的行数 */\n    int  errors;                       /* 出错计数（超长/非法） */\n} parser_t;\n\nvoid parser_init(parser_t *p);\nvoid parser_feed(parser_t *p, const uint8_t *data, int n);\n\n#endif\n\n/* ================= proto.c ================= */\n#include \"proto.h\"\n#include <string.h>\n#include <stdio.h>\n\nstatic const cmd_entry_t g_cmds[CMD_MAX] = {\n    { \"GET_MENU\", cmd_get_menu },\n    { \"ORDER\",    cmd_order    },\n    { \"PAY\",      cmd_pay      },\n    { \"DISPENSE\", cmd_dispense },\n};\n\nvoid parser_init(parser_t *p)\n{\n    if (p == NULL) return;\n    p->len = 0;\n    p->overflow = 0;\n    p->frames = 0;\n    p->errors = 0;\n}\n\nstatic void parser_reset(parser_t *p)\n{\n    p->len = 0;\n    p->overflow = 0;\n}\n\n/* 核心：逐字节喂入，遇到换行即视为一帧 */\nvoid parser_feed(parser_t *p, const uint8_t *data, int n)\n{\n    for (int i = 0; i < n; i++) {\n        char ch = (char)data[i];\n\n        if (ch == '\\r') continue;                 /* 兼容 Windows 风格 \\r\\n */\n\n        if (ch == '\\n') {\n            if (p->overflow) {\n                p->errors++;                      /* 超长行：整行丢弃 */\n            } else if (p->len > 0) {\n                p->line[p->len] = '\\0';           /* 补字符串结束符 */\n                handle_line(p->line);\n                p->frames++;\n            } else {\n                /* 空行（连续两个 \\n）：静默忽略 */\n            }\n            parser_reset(p);\n            continue;\n        }\n\n        if (p->len < LINE_MAX - 1) {\n            p->line[p->len++] = ch;               /* 正常缓存 */\n        } else {\n            p->overflow = 1;                      /* 超长：继续吞到行尾，再整行丢弃 */\n        }\n    }\n}\n\n/* 拆分命令名与参数：\"PAY 10001 1\" → name=\"PAY\", args=\"10001 1\" */\nstatic void handle_line(const char *line)\n{\n    char name[24];\n    int i = 0;\n    while (line[i] != '\\0' && line[i] != ' ' && i < (int)sizeof(name) - 1) {\n        name[i] = line[i];\n        i++;\n    }\n    name[i] = '\\0';\n    const char *args = (line[i] == ' ') ? line + i + 1 : \"\";\n\n    for (int k = 0; k < CMD_MAX; k++) {\n        if (g_cmds[k].name == NULL) continue;\n        if (strcmp(g_cmds[k].name, name) == 0) {\n            g_cmds[k].fn(args);\n            return;\n        }\n    }\n    printf(\"[proto] 未知命令: %s\\n\", name);\n}" },
      { t: "这个设计的三个亮点（面试可以直接讲）",
        h: "<ul><li><b>无状态调用</b>：<code>parser_feed</code> 只依赖传入的 <code>parser_t</code>，不依赖全局变量，可以在多个连接上并存（多客户端场景直接复制一份结构体）</li><li><b>抗粘包/半包</b>：半包留在 <code>line</code> 里等下次 feed 拼接；一个 feed 里有多个 <code>\\n</code> 会连续解析出多帧</li><li><b>可计数、可观测</b>：frames/errors 让运行状态可统计，现场排查时能看出\"到底收没收到包\"</li></ul>" }
    ],
    quiz: [
      { type: "single", q: "一次 parser_feed 只收到了 \"ORD\"（半个命令），解析器会怎么处理？",
        opts: ["立即报错并把数据丢掉", "把 ORD 缓存在 p->line 里，等下一次 feed 收到剩余字节后拼成完整行再解析", "阻塞等待剩余数据", "把 ORD 当成完整命令处理"], ans: 1,
        exp: "这就是状态机抗半包的关键：不完整的数据先存着，指针 <code>len</code> 记住长度，下次接着追加。网络编程里\"半个包\"是常态而不是异常。" },
      { type: "single", q: "行超长时用 overflow 标记而不是立刻返回错误，好处是？",
        opts: ["省内存", "保证解析器仍然能对上\"行边界\"：继续吞字节直到 \\n，然后整行丢弃，后续的行不会因为错位而全部解析失败", "让代码更短", "防止缓冲区溢出"], ans: 1,
        exp: "如果超长就立即中断，剩下的超长内容会被当成新行的开头，后面所有帧都会错位。\"丢弃一整行\"是让系统能继续工作的正确降级方式。" },
      { type: "blank", q: "补全：判断一行是否为空的代码（空行不调用处理函数）。",
        code: "if (ch == '\\n') {\n    if (p->overflow) {\n        p->errors++;\n    } else if ({{0}}) {\n        p->line[p->len] = '\\0';\n        handle_line(p->line);\n    }\n    parser_reset(p);\n}",
        blanks: [{ acc: ["p->len>0", "p->len > 0"] }],
        exp: "用 len > 0 过滤空行。如果不过滤，客户端每发一个 \\n 服务端都会收到一条空命令，日志里全是噪音。" },
      { type: "single", q: "命令分发用函数指针表（cmd_entry_t g_cmds[]）相比一长串 if-else 的主要好处是？",
        opts: ["运行更快十倍", "新增命令只需在表里加一行 + 写一个函数，不用改动分发逻辑；也不必担心 if 链写漏（这是\"开闭原则\"的朴素实现）", "不需要写函数", "可以支持中文命令"], ans: 1,
        exp: "面试常被追问\"命令表你怎么设计\"。答出\"表 + 函数指针，新增命令不改分发代码\"就够了；再补一句\"可以按名字排序后用二分/哈希加速\"更好。" },
      { type: "code", q: "改造任务一：实现 cmd_pay，解析 \"PAY 10001 1\" 这样的参数串（订单号 + 支付方式），要求严格校验参数个数、数值范围，并把非法输入记录到错误计数。",
        hint: "<p>用 sscanf 或 strtol 解析；检查返回值是否为 2；订单号要求 &gt;0，支付方式限定在 1~3；注意 args 可能为空字符串。</p>",
        sol: "static int g_proto_errors;      /* 协议层错误计数，可被日志/STATS 使用 */\n\nvoid cmd_pay(const char *args)\n{\n    if (args == NULL || *args == '\\0') {\n        printf(\"[PAY] 缺少参数\\n\");\n        g_proto_errors++;\n        return;\n    }\n\n    int order_id = 0, method = 0;\n    if (sscanf(args, \"%d %d\", &order_id, &method) != 2) {\n        printf(\"[PAY] 参数格式错误: %s\\n\", args);\n        g_proto_errors++;\n        return;\n    }\n    if (order_id <= 0 || method < 1 || method > 3) {\n        printf(\"[PAY] 参数越界: id=%d method=%d\\n\", order_id, method);\n        g_proto_errors++;\n        return;\n    }\n\n    if (pay_process(order_id, method) != 0)\n        printf(\"[PAY] 支付失败 id=%d\\n\", order_id);\n    else\n        printf(\"[PAY] 支付成功 id=%d\\n\", order_id);\n}",
        exp: "要点：① sscanf 的返回值必须判 2（不是布尔判断）；② 每个参数都要做范围校验——协议层是外部输入的第一道关卡；③ 错误要落到计数/日志，不能只打印一句就完事。" },
      { type: "code", q: "改造任务二：给命令表新增一条 STATS 命令，打印解析统计（成功帧数、错误数、当前缓存长度、水位峰值），并为 parser_t 增加\"峰值缓存\"字段。",
        hint: "<p>要打印解析器状态，处理函数需要能拿到 parser_t 指针——可以声明一个模块内静态指针（由 parser_init 记录），或把状态放进独立的模块级结构。同时记得 g_cmds 数组大小 CMD_MAX 要够用。</p>",
        sol: "/* 1. 结构体加字段 */\ntypedef struct {\n    char line[LINE_MAX];\n    int  len;\n    int  overflow;\n    int  frames;\n    int  errors;\n    int  peak_len;          /* 新增：缓存水位峰值 */\n} parser_t;\n\n/* 2. 在 parser_feed 的缓存分支里更新峰值 */\nif (p->len < LINE_MAX - 1) {\n    p->line[p->len++] = ch;\n    if (p->len > p->peak_len) p->peak_len = p->len;   /* 记录峰值 */\n} else {\n    p->overflow = 1;\n}\n\n/* 3. 模块内记录被初始化的解析器（单实例场景够用） */\nstatic parser_t *g_parser = NULL;\n\nvoid parser_init(parser_t *p)\n{\n    ...\n    g_parser = p;\n}\n\n/* 4. 新增命令处理函数 */\nvoid cmd_stats(const char *args)\n{\n    (void)args;\n    if (g_parser == NULL) { printf(\"[STATS] 解析器未初始化\\n\"); return; }\n    printf(\"[STATS] frames=%d errors=%d pending=%d peak=%d\\n\",\n           g_parser->frames, g_parser->errors,\n           g_parser->len, g_parser->peak_len);\n}\n\n/* 5. 命令表加一行 */\nstatic const cmd_entry_t g_cmds[CMD_MAX] = {\n    { \"GET_MENU\", cmd_get_menu },\n    { \"ORDER\",    cmd_order    },\n    { \"PAY\",      cmd_pay      },\n    { \"DISPENSE\", cmd_dispense },\n    { \"STATS\",    cmd_stats    },     /* 新增 */\n};",
        exp: "这个任务练的是\"扩展能力\"：能不能在不动分发逻辑的前提下加功能，以及\"可观测性\"意识（峰值水位是判断缓冲区够不够的直接依据）。生产代码里这类统计字段极其常见。" }
    ]
  },

  /* ---------------- 第 3 章 ---------------- */
  {
    id: "bc3",
    title: "长代码三：线程池 + 任务队列",
    brief: "并发、锁与生命周期管理（约 170 行）",
    points: [
      { t: "阅读任务：盯住三个关键时刻",
        h: "<ol><li><b>取到任务之后</b>：锁是什么时候释放的？为什么不能在持锁状态下执行任务？</li><li><b>等待任务时</b>：条件变量为什么必须配 <code>while</code>？</li><li><b>销毁时</b>：怎么保证所有线程都退出、内存不泄漏？</li></ol>" },
      { t: "完整实现",
        h: "<p>任务队列 + 工作线程 + 优雅退出。这是嵌入式 Linux 应用开发里最常被问的\"手写并发结构\"。</p>",
        code: "#include <pthread.h>\n#include <stdlib.h>\n#include <stdio.h>\n\n#define POOL_MAX_PENDING 64      /* 积压上限：满了就拒绝，形成背压 */\n\ntypedef struct task {\n    void (*fn)(void *);\n    void *arg;\n    struct task *next;\n} task_t;\n\ntypedef struct {\n    task_t *head, *tail;         /* 队列首尾 */\n    pthread_mutex_t mtx;         /* 保护队列与状态的互斥锁 */\n    pthread_cond_t  cond;        /* 任务到达 / 退出通知 */\n    pthread_t *threads;\n    int nthreads;\n    int pending;                 /* 当前排队任务数 */\n    int shutdown;                /* 退出标志 */\n} pool_t;\n\n/* 工作线程：取任务 → 解锁 → 执行 → 回锁 */\nstatic void *worker(void *arg)\n{\n    pool_t *p = arg;\n\n    for (;;) {\n        pthread_mutex_lock(&p->mtx);\n\n        while (p->head == NULL && !p->shutdown)   /* 必须用 while：防止虚假唤醒 */\n            pthread_cond_wait(&p->cond, &p->mtx);\n\n        if (p->head == NULL && p->shutdown) {     /* 退出：队列空且已通知关闭 */\n            pthread_mutex_unlock(&p->mtx);\n            break;\n        }\n\n        task_t *t = p->head;                      /* 摘一个任务 */\n        p->head = t->next;\n        if (p->head == NULL) p->tail = NULL;\n        p->pending--;\n\n        pthread_mutex_unlock(&p->mtx);            /* 关键：先解锁，再执行任务 */\n\n        t->fn(t->arg);                            /* 执行用户任务（可能很慢） */\n        free(t);\n    }\n    return NULL;\n}\n\nint pool_init(pool_t *p, int nthreads)\n{\n    if (p == NULL || nthreads <= 0) return -1;\n\n    p->head = p->tail = NULL;\n    p->pending = 0;\n    p->shutdown = 0;\n    p->nthreads = nthreads;\n    pthread_mutex_init(&p->mtx, NULL);\n    pthread_cond_init(&p->cond, NULL);\n\n    p->threads = calloc(nthreads, sizeof(pthread_t));\n    if (p->threads == NULL) return -1;\n\n    for (int i = 0; i < nthreads; i++) {\n        if (pthread_create(&p->threads[i], NULL, worker, p) != 0)\n            return -1;                            /* 生产代码这里要回收已建线程 */\n    }\n    return 0;\n}\n\n/* 提交任务：满则返回 -1（背压，让调用者决定丢弃或稍后重试） */\nint pool_submit(pool_t *p, void (*fn)(void *), void *arg)\n{\n    if (p == NULL || fn == NULL) return -1;\n\n    task_t *t = malloc(sizeof(task_t));\n    if (t == NULL) return -1;\n    t->fn = fn;\n    t->arg = arg;\n    t->next = NULL;\n\n    pthread_mutex_lock(&p->mtx);\n    if (p->shutdown || p->pending >= POOL_MAX_PENDING) {\n        pthread_mutex_unlock(&p->mtx);\n        free(t);\n        return -1;\n    }\n    if (p->tail == NULL) p->head = t;\n    else                 p->tail->next = t;\n    p->tail = t;\n    p->pending++;\n    pthread_cond_signal(&p->cond);                /* 唤醒一个线程 */\n    pthread_mutex_unlock(&p->mtx);\n    return 0;\n}\n\n/* 优雅退出：置标志 → 广播 → 回收线程 → 释放残留任务 */\nvoid pool_destroy(pool_t *p)\n{\n    if (p == NULL) return;\n\n    pthread_mutex_lock(&p->mtx);\n    p->shutdown = 1;\n    pthread_cond_broadcast(&p->cond);             /* 必须 broadcast，唤醒所有线程 */\n    pthread_mutex_unlock(&p->mtx);\n\n    for (int i = 0; i < p->nthreads; i++)\n        pthread_join(p->threads[i], NULL);\n\n    task_t *t = p->head;                          /* 队列里可能还剩任务 */\n    while (t) {\n        task_t *next = t->next;\n        free(t);\n        t = next;\n    }\n\n    free(p->threads);\n    pthread_mutex_destroy(&p->mtx);\n    pthread_cond_destroy(&p->cond);\n}" },
      { t: "这段代码里的五个面试考点",
        h: "<ul><li><b>为什么执行任务前解锁</b>：持锁执行会让所有工作线程串行化，线程池形同虚设</li><li><b>为什么 while 而不是 if</b>：虚假唤醒 + 被唤醒后条件可能又变了</li><li><b>为什么 destroy 用 broadcast</b>：signal 只唤醒一个线程，其余会永远等下去</li><li><b>为什么需要 pending 上限</b>：无上限队列在过载时会吃光内存（背压设计）</li><li><b>销毁时为何要释放残留任务</b>：队列里未执行的任务是堆内存，不释放就是泄漏</li></ul>" }
    ],
    quiz: [
      { type: "single", q: "worker 里为什么必须持锁取任务、解锁后再执行任务？",
        opts: ["为了让代码更清晰", "若持锁执行任务，所有工作线程会被串行化——同一时刻只有一个线程能跑，多线程等于白开；而且任务里若再申请同一把锁会直接死锁", "为了减少内存占用", "pthread 标准强制要求"], ans: 1,
        exp: "\"锁保护数据，不保护执行\"——这是并发编程第一原则。锁的粒度决定并发度，把耗时逻辑放进临界区是最常见的性能事故。" },
      { type: "single", q: "pool_destroy 里为什么用 pthread_cond_broadcast 而不是 signal？",
        opts: ["broadcast 更快", "signal 只唤醒一个线程，其它线程会继续等在自己那轮 cond_wait 上，pthread_join 永远等不到它们", "broadcast 会自动释放锁", "两者完全等价"], ans: 1,
        exp: "退出是\"条件对所有线程都成立\"的场景，必须广播。判断口诀：唤醒一个用 signal，条件变化影响所有等待者用 broadcast。" },
      { type: "blank", q: "补全等待循环中的判断（防止虚假唤醒）：",
        code: "pthread_mutex_lock(&p->mtx);\n{{0}} (p->head == NULL && !p->shutdown)\n    pthread_cond_wait(&p->cond, &p->mtx);",
        blanks: [{ acc: ["while"] }],
        exp: "必须 while。虚假唤醒会返回但你等的东西还没到；即使真被唤醒，条件也可能已被别的线程抢走（惊群）。用 if 会让线程在条件不成立时继续往下跑。" },
      { type: "single", q: "pool_submit 里 pending >= POOL_MAX_PENDING 就返回 -1，这个设计叫？",
        opts: ["内存泄漏", "背压（backpressure）：过载时主动拒绝，让上游决定丢弃或重试，避免队列无限增长吃光内存", "死锁", "惊群"], ans: 1,
        exp: "嵌入式设备内存有限，\"无上限队列\"是隐患。真实系统里常见三种策略：拒绝、丢弃最旧、阻塞等待——各有取舍，关键是显式设计而不是默认不管。" },
      { type: "code", q: "改造任务一：给线程池加一个\"等待所有已提交任务执行完毕\"的接口 pool_wait_idle(p, timeout_ms)。要求：任务全部执行完（pending==0）返回 0，超时返回 -1。",
        hint: "<p>需要一个与 pending 配套的条件变量（或复用同一把锁 + 定时等待 pthread_cond_timedwait）。注意 pending 归零的时刻在 worker 里，需要在那里发信号。</p>",
        sol: "/* 1. 结构体增加一个条件变量 */\ntypedef struct {\n    ...\n    pthread_cond_t idle_cond;    /* pending 归零时通知 */\n} pool_t;\n\n/* 2. worker 摘下任务（pending--）后，若队列已空则通知等待者 */\np->pending--;\nif (p->pending == 0)\n    pthread_cond_signal(&p->idle_cond);\n\n/* 3. 新增接口 */\n#include <errno.h>\n#include <time.h>\n#include <sys/time.h>\n\nint pool_wait_idle(pool_t *p, int timeout_ms)\n{\n    struct timespec ts;\n    clock_gettime(CLOCK_REALTIME, &ts);\n    ts.tv_sec  += timeout_ms / 1000;\n    ts.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;\n    if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }\n\n    pthread_mutex_lock(&p->mtx);\n    int rc = 0;\n    while (p->pending > 0 && rc == 0) {\n        rc = pthread_cond_timedwait(&p->idle_cond, &p->mtx, &ts);\n    }\n    int result = (p->pending == 0) ? 0 : -1;\n    pthread_mutex_unlock(&p->mtx);\n    return result;\n}",
        exp: "要点：① 等待必须用 while + 重新判断条件；② 定时等待用 pthread_cond_timedwait（相对时间要先转成绝对时间，且注意 tv_nsec 补位）；③ 超时后必须重新检查条件——可能恰好在超时瞬间完成。" },
      { type: "code", q: "改造任务二：把线程池改造成\"能取回任务结果\"的形式——任务函数返回 int，并用一个完成回调把结果交给提交者（提示：在 task_t 里增加 result 与 done 回调字段）。",
        hint: "<p>不要为了拿返回值就把执行挪回调用线程。做法：task_t 扩展字段，worker 执行完后调用 task 的完成回调；调用者可以在回调里处理结果，或用条件变量等结果。</p>",
        sol: "typedef struct task {\n    void (*fn)(void *);\n    void *arg;\n    void (*done)(int result, void *arg);   /* 完成回调，可为 NULL */\n    struct task *next;\n} task_t;\n\nint pool_submit_ex(pool_t *p, int (*fn)(void *), void (*done)(int, void *), void *arg);\n\n/* worker 中：执行后回调 */\nint rc = t->fn(t->arg);\nif (t->done)\n    t->done(rc, t->arg);\nfree(t);\n\n/* 提交接口：把 fn 包装进 task_t 的 fn 字段（强转或用统一签名） */\nint pool_submit_ex(pool_t *p, int (*fn)(void *), void (*done)(int, void *), void *arg)\n{\n    /* ...同 pool_submit，只是多赋值 done 字段... */\n    t->fn  = (void (*)(void *))fn;      /* 简化写法：也可统一签名避免强转 */\n    t->done = done;\n    t->arg  = arg;\n    /* ...入队... */\n    return 0;\n}\n\n/* 使用示例：\n * pool_submit_ex(&pool, read_sensor, on_sensor_done, &ctx);\n */",
        exp: "这是异步编程的基本功：\"提交任务\"和\"拿结果\"分开，用回调或 future 关联。工业代码里更规范的做法是统一任务签名（如 int (*)(void*)），避免强制转换带来的类型不安全。" }
    ]
  },

  /* ---------------- 第 4 章 ---------------- */
  {
    id: "bc4",
    title: "长代码四：固定块内存池",
    brief: "嵌入式为什么不用 malloc（约 120 行）",
    points: [
      { t: "为什么嵌入式常常自己写内存池",
        h: "<p>标准 <code>malloc</code> 的问题：① 分配时间不确定（最坏情况可能遍历空闲链表）② 长期运行会产生<b>内存碎片</b>，明明总量够却分配不出 ③ 实现可能带锁，中断/实时上下文不适用。固定块内存池用\"空闲链表\"实现 <b>O(1) 分配/释放且零碎片</b>，代价是只能分配固定大小的块。</p>" },
      { t: "完整实现",
        h: "<p>把一整块静态内存切成长度相同的块，用链表串起空闲块。分配 = 从表头摘一个；释放 = 挂回表头。注意对齐与非法指针校验。</p>",
        code: "#include <stdint.h>\n#include <string.h>\n\n#define POOL_BLOCK_SIZE 32\n#define POOL_BLOCK_NUM  64\n\n/* 空闲块的头：复用块自身的空间存 next，不额外占内存 */\ntypedef struct block {\n    struct block *next;\n} block_t;\n\ntypedef struct {\n    uint8_t  mem[POOL_BLOCK_NUM * POOL_BLOCK_SIZE] __attribute__((aligned(8)));\n    block_t *free_list;      /* 空闲链表头 */\n    int      used;           /* 已分配块数 */\n    int      peak;           /* 历史峰值，用于评估容量是否够 */\n    int      err_free;       /* 非法释放计数 */\n} pool_t;\n\nvoid pool_init(pool_t *p)\n{\n    p->free_list = NULL;\n    p->used = 0;\n    p->peak = 0;\n    p->err_free = 0;\n\n    /* 从后往前串，保证分配顺序与内存地址一致（便于调试观察） */\n    for (int i = POOL_BLOCK_NUM - 1; i >= 0; i--) {\n        block_t *b = (block_t *)(p->mem + i * POOL_BLOCK_SIZE);\n        b->next = p->free_list;\n        p->free_list = b;\n    }\n}\n\nvoid *pool_alloc(pool_t *p)\n{\n    if (p->free_list == NULL)\n        return NULL;                       /* 池耗尽：由调用者决定等待或降级 */\n\n    block_t *b = p->free_list;\n    p->free_list = b->next;\n    p->used++;\n    if (p->used > p->peak) p->peak = p->used;\n    memset(b, 0, POOL_BLOCK_SIZE);         /* 清零，避免脏数据被误用 */\n    return b;\n}\n\n/* 释放：校验指针是否合法、是否对齐，防止双重释放破坏链表 */\nint pool_free(pool_t *p, void *ptr)\n{\n    if (ptr == NULL) return -1;\n\n    uintptr_t base = (uintptr_t)p->mem;\n    uintptr_t a = (uintptr_t)ptr;\n\n    if (a < base || a >= base + sizeof(p->mem)) { p->err_free++; return -1; }\n    if (((a - base) % POOL_BLOCK_SIZE) != 0)     { p->err_free++; return -1; }\n\n    block_t *b = (block_t *)ptr;\n    /* 简单防重释放：扫一遍空闲链表看是否已在内 */\n    for (block_t *it = p->free_list; it; it = it->next)\n        if (it == b) { p->err_free++; return -1; }\n\n    b->next = p->free_list;\n    p->free_list = b;\n    p->used--;\n    return 0;\n}\n\nint pool_used(const pool_t *p)  { return p->used; }\nint pool_peak(const pool_t *p)  { return p->peak; }" },
      { t: "分配/释放的复杂度与代价",
        h: "<table><tr><th></th><th>malloc</th><th>固定块内存池</th></tr><tr><td>分配时间</td><td>不确定（可能遍历/合并）</td><td>O(1)，确定</td></tr><tr><td>碎片</td><td>会产生</td><td>无（块等大）</td></tr><tr><td>支持大小</td><td>任意</td><td>仅固定块（可做多级池）</td></tr><tr><td>典型用途</td><td>通用应用</td><td>实时系统、网络包、任务对象</td></tr></table><p>面试答法：\"嵌入式选内存池是为了<b>时间确定性</b>和<b>无碎片</b>，代价是灵活性；如果块大小差异大，就做多级内存池（如 16/32/64/128 字节各一池）。\"</p>" }
    ],
    quiz: [
      { type: "single", q: "固定块内存池能做到 O(1) 分配的根本原因是？",
        opts: ["用了更快的编译器优化", "空闲块被串成链表（或位图），分配就是把表头摘下来、释放就是挂回表头，无需查找合适大小的空洞", "因为它不分配内存", "因为块很小"], ans: 1,
        exp: "malloc 要\"找一块够大的空间\"（可能还要合并相邻空闲块），所以时间不确定；固定块池不存在\"够不够大\"的判断，一步到位。" },
      { type: "single", q: "在 32 位 MCU 上，块大小设为 30 字节、且不做对齐处理，可能出什么问题？",
        opts: ["没有问题", "下一块的起始地址可能不是 4 字节对齐，某些架构（如 ARM Cortex-M0）访问不对齐的 32 位数据会触发硬件异常或性能下降", "内存池会失效", "编译报错"], ans: 1,
        exp: "所以块大小通常取 4/8 的倍数，或给结构体加 aligned 属性。这是\"内存对齐\"在真实项目里的落点，也是面试追问点。" },
      { type: "blank", q: "补全分配逻辑的核心两行：",
        code: "block_t *b = p->free_list;\n{{0}};\np->used++;",
        blanks: [{ acc: ["p->free_list=b->next", "p->free_list = b->next"] }],
        exp: "摘表头：先把空闲链表头指向下一个，再把这块返回给调用者。注意顺序——先改链表再使用，否则链表头就丢了。" },
      { type: "single", q: "pool_free 里做\"指针范围 + 对齐 + 是否已在空闲链表\"三重校验，主要防止？",
        opts: ["提高性能", "非法释放（传错指针/释放未分配的内存）和双重释放——两者都会破坏空闲链表，导致后续分配返回重复地址，引发数据错乱", "节省内存", "兼容 C++"], ans: 1,
        exp: "内存池的\"释放\"只是把块挂回链表，一旦被错误地挂两次，同一块会被分配给两个使用者——这种 bug 极难排查。校验是廉价的保险。" },
      { type: "code", q: "改造任务一：把这个单级内存池改造成\"两级池\"——同时支持 32 字节和 64 字节两种块（提示：各维护一个空闲链表，并提供按尺寸选择的分配接口；无法整除时如何处理要说明）。",
        hint: "<p>结构上可以用两个 pool_t 组合，也可以在一个结构里放两个空闲链表。分配接口接收 size，向上取整到够用的档位（32 或 64）。注意：64 字节的请求不能返回 32 字节的块。</p>",
        sol: "#define BLK_SMALL 32\n#define BLK_LARGE 64\n#define NUM_SMALL 48\n#define NUM_LARGE 16\n\ntypedef struct {\n    uint8_t  mem_s[NUM_SMALL * BLK_SMALL] __attribute__((aligned(8)));\n    uint8_t  mem_l[NUM_LARGE * BLK_LARGE] __attribute__((aligned(8)));\n    block_t *free_s;\n    block_t *free_l;\n    int used_s, used_l;\n} pool2_t;\n\nvoid pool2_init(pool2_t *p);   /* 两个链表分别初始化，同前面 pool_init 的逻辑 */\n\n/* 按尺寸选择档位：\n *   size <= 32 → 小块；size <= 64 → 大块；更大 → 返回 NULL（可扩展第三档）\n */\nvoid *pool2_alloc(pool2_t *p, int size)\n{\n    if (size <= 0) return NULL;\n\n    if (size <= BLK_SMALL) {\n        if (p->free_s == NULL) return NULL;          /* 小块用尽不借大块 */\n        block_t *b = p->free_s;\n        p->free_s = b->next;\n        p->used_s++;\n        memset(b, 0, BLK_SMALL);\n        return b;\n    }\n    if (size <= BLK_LARGE) {\n        if (p->free_l == NULL) return NULL;\n        block_t *b = p->free_l;\n        p->free_l = b->next;\n        p->used_l++;\n        memset(b, 0, BLK_LARGE);\n        return b;\n    }\n    return NULL;      /* 超规格：设计上应扩容档位或改用其他池 */\n}\n\n/* 释放时必须知道块属于哪个池：\n * 做法一：调用者显式传尺寸档位（简单、零开销）\n * 做法二：在块头加 1 字节 tag 记录档位（多占内存但接口更友好）\n */\nint pool2_free(pool2_t *p, void *ptr, int size_hint)\n{\n    if (size_hint <= BLK_SMALL) { /* 挂回 free_s 并做校验 */ }\n    else                        { /* 挂回 free_l 并做校验 */ }\n    return 0;\n}",
        exp: "多级池的核心难点是\"释放时怎么知道该挂回哪个池\"：显式传尺寸（零开销，接口丑）或在块头加 tag（占 1 字节，接口友好）。能说出这个取舍，说明你真在设计而不是抄代码。" },
      { type: "code", q: "改造任务二：写一个针对该内存池的单元测试函数 pool_selftest()，覆盖四种情况：正常分配/释放、耗尽（返回 NULL）、非法指针释放被拒、双重释放被拒。",
        hint: "<p>用断言或返回错误码的方式；测试要能自动跑（启动时调用并打印结果），不要靠人工观察；注意测完之后把池恢复干净（统计 used 回到 0）。</p>",
        sol: "/* 极简断言宏：失败即打印并返回失败计数 */\n#define CHECK(cond, msg)                                                \\\n    do {                                                                \\\n        if (!(cond)) { printf(\"[TEST] FAIL: %s\\n\", msg); fail++; }      \\\n        else         { printf(\"[TEST] ok  : %s\\n\", msg); }              \\\n    } while (0)\n\nint pool_selftest(void)\n{\n    pool_t pool;\n    int fail = 0;\n    pool_init(&pool);\n\n    /* 1. 正常分配与释放 */\n    void *a = pool_alloc(&pool);\n    void *b = pool_alloc(&pool);\n    CHECK(a && b && a != b, \"分配返回不同地址\");\n    CHECK(pool_used(&pool) == 2, \"used 计数正确\");\n    CHECK(pool_free(&pool, a) == 0, \"正常释放成功\");\n    CHECK(pool_free(&pool, b) == 0, \"正常释放成功2\");\n    CHECK(pool_used(&pool) == 0, \"释放后 used 归零\");\n\n    /* 2. 耗尽 */\n    void *arr[POOL_BLOCK_NUM + 1];\n    int got = 0;\n    for (int i = 0; i <= POOL_BLOCK_NUM; i++) {\n        arr[i] = pool_alloc(&pool);\n        if (arr[i] == NULL) break;\n        got++;\n    }\n    CHECK(got == POOL_BLOCK_NUM, \"最多只能分配 POOL_BLOCK_NUM 块\");\n    CHECK(pool_alloc(&pool) == NULL, \"耗尽后返回 NULL\");\n\n    /* 3. 非法指针 */\n    int local = 0;\n    CHECK(pool_free(&pool, &local) != 0, \"拒绝池外指针\");\n    CHECK(pool_free(&pool, NULL) != 0, \"拒绝 NULL\");\n\n    /* 4. 双重释放 */\n    CHECK(pool_free(&pool, arr[0]) == 0, \"第一次释放成功\");\n    CHECK(pool_free(&pool, arr[0]) != 0, \"双重释放被拒\");\n\n    /* 清理：把剩余块还回去并核对 */\n    for (int i = 1; i < got; i++) pool_free(&pool, arr[i]);\n    CHECK(pool_used(&pool) == 0, \"测试结束池已清空\");\n    CHECK(pool.err_free >= 3, \"非法释放计数生效\");\n\n    printf(\"[TEST] %s (fail=%d)\\n\", fail ? \"FAILED\" : \"PASSED\", fail);\n    return fail;\n}",
        exp: "\"能写测试\"是初级和中级的分水岭。这类自检函数在真实固件里常挂在启动自检或出厂测试模式下运行——面试时提到\"我给自己写的容器写过自测\"，加分会很明显。" }
    ]
  }
  ]
});


/* ==== data-proj2.js ==== */

/* ============================================================
   课程十二：综合项目训练营
   三个"能写进简历"的完整工程：数据上报系统 / 配置与日志模块 / OTA 升级包
   每章 = 需求与架构 + 模块划分 + 分步动手任务
   ============================================================ */
window.COURSES = window.COURSES || [];
window.COURSES.push({
  id: "proj2",
  badge: "工程",
  badgeCls: "cb-proj2",
  title: "综合项目训练营",
  brief: "三个完整工程，从需求到交付",
  desc: "设备数据上报系统、配置与日志模块、OTA 固件升级包。每个项目都有架构设计、模块划分和 4 个动手任务，做完可以直接写进简历讲。",
  goal: "能独立完成带通信、存储与多线程协作的完整工程，并正确处理异常路径与资源回收。",
  roles: ["mcu", "rtos", "linux", "drv", "iot"],
  dep: ["lx", "camp"],
  chapters: [

  /* ---------------- 第 1 章 ---------------- */
  {
    id: "pj1",
    title: "项目一：设备数据采集上报系统",
    brief: "多线程 + 环形缓冲 + TCP 上报 + 断线重连",
    points: [
      { t: "需求与验收标准",
        h: "<p><b>需求</b>：一个采集终端程序，周期性读取传感器数据（模拟），通过 TCP 上报到服务器；服务器不可达时不能丢数据、不能卡死，恢复后自动续传。</p><p><b>验收标准（拿这些标准检验自己）</b>：</p><ul><li>断网 30 秒再恢复，程序不崩、不卡、数据不丢（靠本地缓冲排队）</li><li>CPU 占用合理（不允许忙等空转）</li><li>Ctrl+C 能优雅退出：不产生僵尸线程、不留泄漏</li><li>日志能看出\"采集了多少、发出多少、因缓冲满丢弃多少\"</li></ul>" },
      { t: "架构设计：三个线程 + 一个缓冲区",
        h: "<p>数据流：<b>采集线程</b> → 环形缓冲区（线程安全）→ <b>网络线程</b> → 服务器；<b>主线程</b>只负责初始化、等信号、收尾。</p><p>目录结构建议这样分，每个模块一个 .c/.h：</p>",
        code: "proj/\n├── main.c            初始化、信号处理、等待退出\n├── collector.c/.h    采集线程：周期采样写缓冲\n├── net.c/.h          网络线程：连接、发送、重连\n├── ringbuf.c/.h      环形缓冲区（可直接用上一门课的实现）\n├── protocol.c/.h     上报报文打包\n├── config.c/.h       参数配置（采集周期、服务器地址）\n├── log.c/.h          日志（分级、线程安全）\n└── Makefile" },
      { t: "三个线程各自的职责与约束",
        h: "<table><tr><th>线程</th><th>做什么</th><th>绝不做</th></tr><tr><td>采集线程</td><td>周期读传感器、打包、写缓冲；缓冲满则计数丢弃</td><td>不阻塞在网络 IO 上</td></tr><tr><td>网络线程</td><td>连接、发送、失败后退避重连；发送成功才从缓冲移除</td><td>不 sleep 死等、不无限阻塞 recv</td></tr><tr><td>主线程</td><td>初始化、等待退出信号、join、清理</td><td>不参与数据处理</td></tr></table><p>面试常问\"为什么不用一个线程轮询搞定\"——答：网络不可靠（可能阻塞数秒），会拖垮采集节奏，分离线程才能保证<b>采集周期稳定</b>。</p>" },
      { t: "动手任务清单（4 步）",
        h: "<ol><li>采集线程：周期采样 + 写入缓冲 + 丢弃计数</li><li>协议打包：长度前缀 + CSV 负载 + 校验</li><li>网络线程：带退避的重连主循环 + 超时发送</li><li>优雅退出：SIGINT 处理 + 线程 join + 资源释放</li></ol><p>建议真机/虚拟机跑起来，用 <code>nc -l 8888</code> 当假服务器接收数据，然后中途 Ctrl+C 模拟服务器掉线，观察程序行为。</p>" }
    ],
    quiz: [
      { type: "single", q: "为什么采集和网络发送要分成两个线程，而不是在一个线程里顺序执行？",
        opts: ["代码看起来更专业", "网络发送可能因链路问题阻塞几十毫秒到几秒；放在同一线程会让采集周期被拖长、时间戳失真。分离后采集节奏稳定，慢的部分由缓冲区吸收", "多线程一定更快", "TCP 不支持单线程"], ans: 1,
        exp: "\"把不确定耗时的部分隔离出去\"是实时系统的核心思路。代价是要处理线程安全与退出同步——这正是本项目的训练重点。" },
      { type: "judge", q: "网络线程应该先调用 rb_read() 从缓冲区取出数据再发送；如果发送失败，把数据重新塞回缓冲区。", ans: false,
        exp: "错误。\"取出→失败→塞回\"会打乱顺序（后塞的排到前面），重连后数据乱序。正确做法：<b>先窥探（peek）不消费，发送成功后再消费</b>，或者取出后失败就自己持有，下次先发它。" },
      { type: "code", q: "任务一：实现采集线程。要求：每 interval_ms 采样一次（sample_sensor() 返回 double），打包成一行文本写进共享环形缓冲区；缓冲满时计数丢弃而不是阻塞；退出标志置位后线程结束。",
        hint: "<p>用 clock_nanosleep 或 usleep 控制周期（注意累积误差）；写缓冲用 rb_write（上一门课实现）；共享的 run 标志用 volatile 或原子量；丢弃计数用互斥锁保护或直接 volatile int（只增不减的统计量）。</p>",
        sol: "typedef struct {\n    ringbuf_t *rb;\n    int        interval_ms;\n    volatile int *run;          /* 退出标志，主线程置 0 */\n    volatile unsigned long sent;    /* 统计：入队条数 */\n    volatile unsigned long dropped; /* 统计：因缓冲满丢弃 */\n} collector_ctx_t;\n\nvoid *collector_thread(void *arg)\n{\n    collector_ctx_t *ctx = arg;\n    char line[128];\n\n    while (*ctx->run) {\n        double v = sample_sensor();              /* 采样（可能耗时几十微秒） */\n        int n = snprintf(line, sizeof(line), \"%.3f\\n\", v);\n\n        int written = rb_write(ctx->rb, (const uint8_t *)line, n);\n        if (written == n) {\n            ctx->sent++;\n        } else {\n            /* 空间不足：丢弃本次数据并计数，绝不阻塞、绝不覆盖未发送数据 */\n            ctx->dropped++;\n        }\n\n        usleep((useconds_t)ctx->interval_ms * 1000);   /* 简单周期控制 */\n    }\n    return NULL;\n}",
        exp: "要点：① 缓冲满时选择\"丢弃并计数\"而不是阻塞——采集线程阻塞会连锁拖慢整个系统；② 统计量用 volatile 让主线程能读；③ 周期用 usleep，若要求更精确应记录上次时间做补偿（避免累积漂移）。" },
      { type: "code", q: "任务二：实现上报报文打包。协议：4 字节大端长度前缀 + CSV 负载 \"DEV01,1700000000,25.6\\n\"。要求提供 pack_report(dev_id, ts, value, buf, size) 接口，返回完整报文长度或 -1。",
        hint: "<p>负载部分用 snprintf 生成再算长度；长度前缀按大端写入（手动移位，或 htonl）。缓冲区要同时容纳 4 字节头 + 负载；记得处理 snprintf 截断。</p>",
        sol: "#include <string.h>\n#include <stdio.h>\n#include <stdint.h>\n\n/* 4 字节大端长度 + 负载；返回总长度，失败返回 -1 */\nint pack_report(const char *dev_id, uint32_t ts, double value,\n                uint8_t *buf, int size)\n{\n    if (dev_id == NULL || buf == NULL || size < 8) return -1;\n\n    /* 1. 先生成负载到临时缓冲，便于算长度 */\n    char payload[192];\n    int plen = snprintf(payload, sizeof(payload), \"%s,%u,%.2f\\n\",\n                        dev_id, ts, value);\n    if (plen < 0 || plen >= (int)sizeof(payload)) return -1;\n\n    if (plen + 4 > size) return -1;          /* 目标缓冲放不下 */\n\n    /* 2. 写 4 字节大端长度前缀（网络字节序） */\n    uint32_t net_len = (uint32_t)plen;\n    buf[0] = (uint8_t)((net_len >> 24) & 0xFF);\n    buf[1] = (uint8_t)((net_len >> 16) & 0xFF);\n    buf[2] = (uint8_t)((net_len >>  8) & 0xFF);\n    buf[3] = (uint8_t)( net_len        & 0xFF);\n\n    memcpy(buf + 4, payload, (size_t)plen);\n    return plen + 4;\n}",
        exp: "要点：① 长度前缀用大端（网络字节序），自己移位或 htonl 都行，但两端必须一致；② 先算负载长度再判断缓冲是否够用；③ 长度前缀 + 校验是自定义协议最常用的划界方式，服务端按长度读满一帧即可。" },
      { type: "code", q: "任务三：实现网络线程的\"带退避重连\"主循环。要求：连接失败后按 1s → 2s → 4s → 最大 10s 退避重试；连接成功后从缓冲区窥探数据并发送，发送成功才消费；每次循环都能被退出标志打断。",
        hint: "<p>退避用变量累乘、封顶；每次重试前把等待时间切成小块（如 100ms）检查退出标志，否则 Ctrl+C 要等满 10 秒才响应；发送用 send 全量写；断线（send 返回 -1 或 0）就关闭 fd 回到重连流程。</p>",
        sol: "void *net_thread(void *arg)\n{\n    net_ctx_t *ctx = arg;\n    int backoff = 1000;              /* 起始 1 秒 */\n    int fd = -1;\n\n    while (*ctx->run) {\n        /* 1. 确保连接 */\n        if (fd < 0) {\n            fd = tcp_connect(ctx->host, ctx->port, 2000);   /* 带超时连接 */\n            if (fd < 0) {\n                LOG_I(\"net\", \"connect failed, retry in %d ms\", backoff);\n                /* 可被打断的等待：切成 100ms 小块检查退出标志 */\n                for (int waited = 0; waited < backoff && *ctx->run; waited += 100)\n                    usleep(100 * 1000);\n                backoff = backoff * 2;\n                if (backoff > 10000) backoff = 10000;          /* 封顶 10s */\n                continue;\n            }\n            LOG_I(\"net\", \"connected\");\n            backoff = 1000;                                  /* 成功后退避复位 */\n        }\n\n        /* 2. 有数据就发：先窥探，发送成功再消费 */\n        uint8_t head[4];\n        if (rb_peek_n(ctx->rb, head, 4) != 4) {              /* 不足一帧头 */\n            usleep(20 * 1000);\n            continue;\n        }\n        uint32_t plen = ((uint32_t)head[0] << 24) | ((uint32_t)head[1] << 16) |\n                        ((uint32_t)head[2] << 8)  |  (uint32_t)head[3];\n        if (plen == 0 || plen > 512) {                       /* 非法帧：丢一帧保护自己 */\n            uint8_t tmp[512];\n            rb_read(ctx->rb, tmp, plen + 4);\n            continue;\n        }\n        if (rb_available(ctx->rb) < plen + 4) { usleep(20 * 1000); continue; }\n\n        uint8_t frame[516];\n        rb_peek_n(ctx->rb, frame, plen + 4);                 /* 只看不取 */\n        if (send_all(fd, frame, plen + 4, 2000) != 0) {      /* 发送失败 */\n            LOG_E(\"net\", \"send failed, reconnect\");\n            close(fd);\n            fd = -1;                                         /* 回重连流程，数据仍在缓冲里 */\n            continue;\n        }\n        rb_read(ctx->rb, frame, plen + 4);                   /* 发送成功才消费 */\n        ctx->reported++;\n    }\n\n    if (fd >= 0) close(fd);\n    return NULL;\n}",
        exp: "三个关键设计：① 退避封顶 + 成功复位，避免疯狂重连把服务器打挂；② 等待要可被打断（切小块检查退出标志），否则退出响应迟钝；③ <b>发送成功才消费缓冲</b>——这是\"不丢数据\"的核心，代价是可能重发（配合服务端幂等）。" },
      { type: "code", q: "任务四：实现优雅退出。要求：捕获 SIGINT/SIGTERM；信号处理函数里只置退出标志（不做任何耗时/非异步安全操作）；主线程等待线程结束、join、释放资源、打印最终统计。",
        hint: "<p>信号处理函数里只能调用异步信号安全函数（write 可以，printf/malloc/free 不行）；退出标志用 volatile sig_atomic_t；主线程 join 所有线程后再销毁互斥锁/条件变量，最后打印统计。</p>",
        sol: "#include <signal.h>\n#include <pthread.h>\n\nstatic volatile sig_atomic_t g_run = 1;    /* 异步信号安全的标志类型 */\n\nstatic void on_signal(int sig)\n{\n    (void)sig;\n    g_run = 0;                              /* 只做这一件事：绝不 printf/malloc */\n}\n\nint main(void)\n{\n    struct sigaction sa;\n    memset(&sa, 0, sizeof(sa));\n    sa.sa_handler = on_signal;              /* 也可用 SA_RESTART 让被中断的系统调用自动重启 */\n    sigaction(SIGINT,  &sa, NULL);\n    sigaction(SIGTERM, &sa, NULL);\n\n    collector_ctx_t cctx;\n    net_ctx_t       nctx;\n    ringbuf_t       rb;\n\n    rb_init(&rb);\n    cctx.rb = &rb; cctx.run = (volatile int *)&g_run; cctx.interval_ms = 200;\n    nctx.rb = &rb; nctx.run = (volatile int *)&g_run;\n\n    pthread_t t_collect, t_net;\n    pthread_create(&t_collect, NULL, collector_thread, &cctx);\n    pthread_create(&t_net,     NULL, net_thread,       &nctx);\n\n    while (g_run) {                         /* 主线程只等待 */\n        sleep(1);\n    }\n\n    LOG_I(\"main\", \"stopping...\");\n    pthread_join(t_collect, NULL);           /* 等线程真正结束再清理资源 */\n    pthread_join(t_net,     NULL);\n\n    LOG_I(\"main\", \"collected=%lu reported=%lu dropped=%lu buffered=%u\",\n          cctx.sent, nctx.reported, cctx.dropped, rb_available(&rb));\n    return 0;\n}",
        exp: "三条铁律：① 信号处理函数只置标志（printf/malloc 都不是异步信号安全的，会在里面死锁）；② 用 volatile sig_atomic_t 而不是普通 int；③ join 之后再销毁资源——顺序反了会出现\"线程还在用已销毁的锁\"。面试问\"程序怎么优雅退出\"，答这三点就够。" }
    ]
  },

  /* ---------------- 第 2 章 ---------------- */
  {
    id: "pj2",
    title: "项目二：配置模块与日志模块",
    brief: "每个真实项目都要有的两个基础件",
    points: [
      { t: "需求：配置与日志",
        h: "<p><b>配置模块</b>：从文本文件读取参数（key=value 格式，支持 # 注释、空行、前后空格），提供带默认值的读取接口。</p><p><b>日志模块</b>：分级输出（DEBUG/INFO/WARN/ERROR）、带时间戳与模块名、线程安全、按大小轮转（超过 1MB 就把 log → log.1 并重开）。</p><p>别看这两个模块小，它们是面试里\"你项目怎么组织的\"最容易被追问的细节。</p>" },
      { t: "配置文件格式设计",
        h: "<p>格式越简单越不容易出错。约定：<code>#</code> 开头是注释；<code>key=value</code>；值两侧空白自动去掉；找不到文件时全部用默认值启动（不能因为配置缺失就崩溃）。</p>",
        code: "# device.conf\n# 采集上报配置\ndev_id = DEV01\ninterval_ms = 200\nserver_host = 192.168.1.100\nserver_port = 8888\nbackoff_max_ms = 10000" },
      { t: "模块接口设计（先写接口再写实现）",
        h: "<p>好接口的特征：调用者不用关心内部结构；失败有明确返回；不需要的细节不暴露。</p>",
        code: "/* config.h */\ntypedef struct cfg cfg_t;\n\ncfg_t *cfg_load(const char *path);        /* 失败也返回可用对象（全默认值） */\nint    cfg_get_int(const cfg_t *c, const char *key, int def);\nconst char *cfg_get_str(const cfg_t *c, const char *key, const char *def);\nvoid   cfg_free(cfg_t *c);\n\n/* log.h */\n#define LOG_DEBUG 0\n#define LOG_INFO  1\n#define LOG_WARN  2\n#define LOG_ERR   3\n\nint  log_init(const char *path, int level, int max_size_kb);\nvoid log_write(int level, const char *tag, const char *fmt, ...);\nvoid log_close(void);\n\n#define LOGI(tag, ...) log_write(LOG_INFO,  tag, __VA_ARGS__)\n#define LOGE(tag, ...) log_write(LOG_ERR,   tag, __VA_ARGS__)" },
      { t: "动手任务清单（4 步）",
        h: "<ol><li>配置解析：逐行读、去空白、跳注释、拆 key/value、处理边界</li><li>配置读取接口：get_int / get_str 带默认值</li><li>线程安全日志：互斥锁 + 时间戳 + 分级过滤</li><li>日志轮转：超过阈值重命名并重开，保证 fd 与锁状态一致</li></ol>" }
    ],
    quiz: [
      { type: "single", q: "配置文件不存在时，cfg_load 的最佳行为是？",
        opts: ["返回 NULL，让所有调用者都判空", "返回一个\"全部使用默认值\"的对象，并记录一条 WARN 日志——程序能继续启动，只是用了默认参数", "直接 exit(1) 退出", "自动创建一份配置文件"], ans: 1,
        exp: "\"缺配置\"是可预期的正常情况，不应该让程序崩溃，也不该把判空负担丢给每个调用者。返回可用对象 + 日志告知，是工程上最省心的设计（也让首次部署更顺）。" },
      { type: "blank", q: "补全配置解析里去掉行尾换行与空白的判断（用 strcspn 定位换行符）：",
        code: "if (fgets(line, sizeof(line), fp) == NULL) break;\nline[{{0}}] = '\\0';      /* 去掉换行符 */",
        blanks: [{ acc: ["strcspn(line,\"\\n\")", "strcspn(line, \"\\n\")"] }],
        exp: "strcspn(line, \"\\n\") 返回换行符所在位置（没有则返回字符串长度），把它替换成 '\\0' 是行读取的标准收尾动作。" },
      { type: "code", q: "任务一：实现配置解析 cfg_load()。要求：逐行读取；跳过空行与 # 注释；按第一个 '=' 拆分 key 与 value；两侧空白与换行全部去掉；非法行（没有 '='）忽略并计数；最多缓存 64 个键值对。",
        hint: "<p>注意\"按第一个 = 拆分\"（value 里可能含 =）；去掉两侧空白要处理空白 + 换行（否则值里带 \\n，后面比较全都不相等）；字符串要拷贝保存，不能存指向行缓冲的指针。</p>",
        sol: "#define CFG_MAX 64\n#define KEY_MAX 32\n#define VAL_MAX 128\n\nstruct cfg {\n    int  n;\n    char keys[CFG_MAX][KEY_MAX];\n    char vals[CFG_MAX][VAL_MAX];\n};\n\n/* 去掉字符串两端空白（含换行、制表符） */\nstatic char *trim(char *s)\n{\n    while (*s == ' ' || *s == '\\t' || *s == '\\r' || *s == '\\n') s++;\n    char *end = s + strlen(s);\n    while (end > s && (end[-1] == ' ' || end[-1] == '\\t' ||\n                       end[-1] == '\\r' || end[-1] == '\\n')) end--;\n    *end = '\\0';\n    return s;\n}\n\ncfg_t *cfg_load(const char *path)\n{\n    cfg_t *c = calloc(1, sizeof(cfg_t));\n    if (c == NULL) return NULL;\n\n    FILE *fp = fopen(path, \"r\");\n    if (fp == NULL) {\n        LOGW(\"cfg\", \"%s not found, use defaults\", path);\n        return c;                       /* 关键：仍然返回可用对象 */\n    }\n\n    char line[256];\n    int  bad = 0;\n    while (fgets(line, sizeof(line), fp) != NULL) {\n        char *p = trim(line);\n        if (*p == '\\0' || *p == '#') continue;    /* 空行与注释 */\n\n        char *eq = strchr(p, '=');\n        if (eq == NULL) { bad++; continue; }       /* 非法行：忽略并计数 */\n\n        *eq = '\\0';\n        char *k = trim(p);\n        char *v = trim(eq + 1);\n        if (*k == '\\0') { bad++; continue; }\n        if (strlen(k) >= KEY_MAX || strlen(v) >= VAL_MAX) { bad++; continue; }\n        if (c->n >= CFG_MAX) { bad++; continue; }\n\n        strcpy(c->keys[c->n], k);                  /* 拷贝保存，不能存指针 */\n        strcpy(c->vals[c->n], v);\n        c->n++;\n    }\n    fclose(fp);\n\n    if (bad) LOGW(\"cfg\", \"%d invalid line(s) ignored\", bad);\n    LOGI(\"cfg\", \"loaded %d items from %s\", c->n, path);\n    return c;\n}",
        exp: "三个易错点：① 必须按第一个 '=' 拆分（value 里可能有 =）；② 去掉尾部 \\n，否则值比较、转数字都会出问题（atoi 能容忍但字符串比较不能）；③ 必须 strcpy 保存内容——存指向局部行缓冲的指针，函数返回后全是野数据。" },
      { type: "code", q: "任务二：实现 cfg_get_int 与 cfg_get_str。要求：找不到 key 时返回传入的默认值；cfg_get_int 要校验数值合法性（非数字时不返回垃圾值）；cfg_get_str 返回值不能因为内部缓冲释放而失效。",
        hint: "<p>cfg_get_int 用 strtol 并检查 endptr 是否指向结尾；cfg_get_str 返回内部存储的指针即可（生命周期与 cfg_t 一致），并在注释里写明这个约定。</p>",
        sol: "const char *cfg_get_str(const cfg_t *c, const char *key, const char *def)\n{\n    if (c == NULL || key == NULL) return def;\n    for (int i = 0; i < c->n; i++) {\n        if (strcmp(c->keys[i], key) == 0)\n            return c->vals[i];        /* 指向 cfg_t 内部存储：生命周期与 cfg_t 相同 */\n    }\n    return def;                        /* 找不到就用默认值 */\n}\n\nint cfg_get_int(const cfg_t *c, const char *key, int def)\n{\n    if (c == NULL || key == NULL) return def;\n    for (int i = 0; i < c->n; i++) {\n        if (strcmp(c->keys[i], key) != 0) continue;\n\n        char *end = NULL;\n        long v = strtol(c->vals[i], &end, 10);\n        if (end == c->vals[i] || *end != '\\0')\n            return def;                /* 不是合法数字：用默认值，绝不返回垃圾 */\n        if (v < INT_MIN || v > INT_MAX)\n            return def;                /* 越界保护 */\n        return (int)v;\n    }\n    return def;\n}",
        exp: "接口设计上的两个专业细节：① 用 strtol + endptr 判断\"整串是不是数字\"（atoi 无法区分 \"abc\" 和 \"0\"）；② 明确返回值的生命周期（指向内部存储）并写进注释——这类约定不清是 C 接口 bug 的高发区。" },
      { type: "code", q: "任务三：实现线程安全的 log_write(level, tag, fmt, ...)。要求：低于当前级别的日志直接丢弃；输出格式 \"[时间] [级别] [模块] 内容\"；多线程写入不串行错乱；写入失败不影响业务。",
        hint: "<p>用互斥锁保护整个\"格式化 + 写入\"过程；时间戳用 localtime_r（线程安全版本）；用 vsnprintf 格式化到栈上缓冲；如果是终端输出还要 fflush，否则崩溃时最后几行日志会丢在缓冲里。</p>",
        sol: "#include <pthread.h>\n#include <stdarg.h>\n#include <time.h>\n\nstatic FILE *g_fp = NULL;\nstatic int   g_level = LOG_INFO;\nstatic pthread_mutex_t g_log_mtx = PTHREAD_MUTEX_INITIALIZER;\nstatic const char *g_level_name[] = { \"DEBUG\", \"INFO\", \"WARN\", \"ERROR\" };\n\nvoid log_write(int level, const char *tag, const char *fmt, ...)\n{\n    if (level < g_level) return;                 /* 级别过滤：先判断，减少锁竞争 */\n\n    /* 1. 先在锁外格式化成字符串（耗时操作放锁外，缩短临界区） */\n    char body[512];\n    va_list ap;\n    va_start(ap, fmt);\n    vsnprintf(body, sizeof(body), fmt, ap);\n    va_end(ap);\n\n    char ts[32];\n    time_t now = time(NULL);\n    struct tm tmv;\n    localtime_r(&now, &tmv);                     /* 线程安全版本 */\n    strftime(ts, sizeof(ts), \"%Y-%m-%d %H:%M:%S\", &tmv);\n\n    /* 2. 加锁只做写入，保证一行日志不被别的线程穿插 */\n    pthread_mutex_lock(&g_log_mtx);\n    if (g_fp != NULL) {\n        fprintf(g_fp, \"[%s] [%s] [%s] %s\\n\", ts,\n                g_level_name[level], tag ? tag : \"-\", body);\n        if (g_fp == stdout || g_fp == stderr)\n            fflush(g_fp);                        /* 终端输出立即刷，崩溃时日志不丢 */\n        else\n            log_maybe_rotate();                  /* 文件输出：检查是否该轮转 */\n    }\n    pthread_mutex_unlock(&g_log_mtx);\n}",
        exp: "三个专业习惯：① 临界区尽量小（格式化在锁外做）；② localtime 不是线程安全的，要用 localtime_r；③ 终端输出要 fflush——程序段错误时缓冲区里的日志会全部丢失，那是你最需要日志的时刻。" },
      { type: "code", q: "任务四：实现日志轮转 log_maybe_rotate()。要求：当前文件超过 max_size_kb 时，把 log → log.1（覆盖旧的 .1），重新打开新文件；轮转失败不能影响后续日志（可以退回 stdout）；轮转后必须保持内部状态一致。",
        hint: "<p>用 ftell(fseek(fp, 0, SEEK_END)) 或 stat 获取当前大小；先 fclose 再 rename，然后重新 fopen 并把新 FILE* 写回全局；注意这个函数是在<b>已持锁</b>的情况下被调用的（不要再加锁，否则死锁）。</p>",
        sol: "static char g_path[256];\nstatic long g_max_bytes = 1024 * 1024;\n\n/* 调用前提：已经持有 g_log_mtx（见 log_write），这里不能再加锁 */\nstatic void log_maybe_rotate(void)\n{\n    if (g_fp == NULL || g_path[0] == '\\0') return;\n\n    long pos = ftell(g_fp);\n    if (pos < 0 || pos < g_max_bytes) return;     /* 未到阈值 */\n\n    fclose(g_fp);\n    g_fp = NULL;\n\n    char oldpath[300];\n    snprintf(oldpath, sizeof(oldpath), \"%s.1\", g_path);\n    if (rename(g_path, oldpath) != 0) {\n        /* 轮转失败：尽量恢复写原文件，实在不行退回 stdout，别丢日志能力 */\n    }\n\n    g_fp = fopen(g_path, \"a\");\n    if (g_fp == NULL)\n        g_fp = stdout;                            /* 兜底：保证日志功能不消失 */\n}\n\n/* 对外接口里做长度与路径校验 */\nint log_init(const char *path, int level, int max_size_kb)\n{\n    if (path == NULL || strlen(path) >= sizeof(g_path)) return -1;\n\n    pthread_mutex_lock(&g_log_mtx);\n    if (g_fp && g_fp != stdout && g_fp != stderr) fclose(g_fp);\n\n    strncpy(g_path, path, sizeof(g_path) - 1);\n    g_path[sizeof(g_path) - 1] = '\\0';\n    g_level = level;\n    g_max_bytes = (long)max_size_kb * 1024;\n    if (g_max_bytes <= 0) g_max_bytes = 1024 * 1024;\n\n    g_fp = fopen(g_path, \"a\");\n    if (g_fp == NULL) g_fp = stdout;\n    pthread_mutex_unlock(&g_log_mtx);\n    return 0;\n}",
        exp: "最关键的坑：log_maybe_rotate 是在已持锁的调用链里执行的，如果再 pthread_mutex_lock 同一把非递归锁 → 自锁死。这是\"内部函数必须写明调用前提\"的经典案例。轮转本身用 rename（原子）而不是拷贝+删除。" }
    ]
  },

  /* ---------------- 第 3 章 ---------------- */
  {
    id: "pj3",
    title: "项目三：OTA 固件升级包",
    brief: "包格式 + CRC32 + 校验 + 升级落地",
    points: [
      { t: "需求：一个能经得起拷问的升级包",
        h: "<p>固件升级最怕两件事：<b>刷了坏包变砖</b>、<b>刷完不会回滚</b>。所以升级包必须自带校验信息，升级流程必须有校验环节和回退方案。</p><p><b>包格式</b>（头 24 字节 + 负载）：</p><table><tr><th>字段</th><th>大小</th><th>作用</th></tr><tr><td>magic</td><td>4</td><td>固定标识，快速识别\"这是不是我们的包\"</td></tr><tr><td>version</td><td>4</td><td>固件版本号，用于防降级</td></tr><tr><td>payload_len</td><td>4</td><td>负载长度，用于校验文件完整性与分配缓冲</td></tr><tr><td>payload_crc</td><td>4</td><td>负载 CRC32，核心校验</td></tr><tr><td>header_crc</td><td>4</td><td>头部自身 CRC，防止头部被篡改（前 20 字节的 CRC）</td></tr><tr><td>payload</td><td>变长</td><td>真正的固件数据</td></tr></table>" },
      { t: "CRC32 为什么用查表法，以及流式接口",
        h: "<p>逐位计算的 CRC32 每个字节要循环 8 次，太慢；预先算好 256 项的表，每个字节只需一次查表 + 异或 + 移位。校验大文件时还要支持<b>分块流式</b>计算，避免把整个固件读进内存。</p>",
        code: "uint32_t crc32_begin(void);                                  /* 起始值 0xFFFFFFFF */\nuint32_t crc32_update(uint32_t c, const uint8_t *p, size_t n); /* 逐块喂入 */\nuint32_t crc32_finish(uint32_t c);                            /* 末尾取反 */\nuint32_t crc32_calc(const uint8_t *p, size_t n);              /* 一次性计算 */" },
      { t: "升级流程与回滚设计",
        h: "<ol><li>下载/拷贝升级包到设备临时分区（不能覆盖正在运行的固件）</li><li><b>verify</b>：校验 magic → 头 CRC → 长度合理性 → 负载 CRC（任何一步失败立即拒绝）</li><li><b>apply</b>：写入目标分区 → <b>回读比对</b> → 打升级标记 → 重启</li><li><b>启动确认</b>：新固件启动后置\"启动成功\"标记；若连续 N 次没能置位，bootloader 自动回滚到旧分区</li></ol><p>面试加分点：说清\"为什么要 A/B 双分区\"——因为不能原地覆盖正在运行的固件，且必须能回滚。</p>" },
      { t: "动手任务清单（4 步）",
        h: "<ol><li>CRC32：生成查表 + 流式接口 + 用标准向量自测</li><li>pack：打包工具，写入头部（含头 CRC）+ 负载 + 负载 CRC</li><li>verify：校验升级包，逐项拒绝非法包</li><li>apply：写目标分区 + 回读比对 + 标记 + 重启</li></ol><p><b>自测向量</b>：CRC32(\"123456789\") = 0xCBF43926。写不出这个值，说明你的 CRC 实现有问题。</p>" }
    ],
    quiz: [
      { type: "single", q: "升级包头部为什么除了 payload_crc 还要再算一个 header_crc？",
        opts: ["为了凑够 24 字节", "payload_crc 保护的是数据，无法发现头部被改动（例如有人改小 payload_len 让你只校验一部分）；header_crc 保护头部自身，两者结合才能覆盖全包", "为了兼容旧版本", "减少计算量"], ans: 1,
        exp: "这是\"完整性校验要覆盖所有可变字段\"的思想。工程上更严谨的做法是直接对整个包（头+负载）做签名/CRC，头部校验则用于尽早发现明显损坏的包。" },
      { type: "blank", q: "补全 CRC32 标准算法的起始与结束处理：",
        code: "uint32_t crc32_calc(const uint8_t *p, size_t n)\n{\n    uint32_t c = {{0}};\n    for (size_t i = 0; i < n; i++)\n        c = g_table[(c ^ p[i]) & 0xFF] ^ (c >> 8);\n    return c ^ 0xFFFFFFFFu;\n}",
        blanks: [{ acc: ["0xFFFFFFFFu", "0xFFFFFFFF"] }],
        exp: "标准 CRC32（IEEE 802.3）起始值取全 1、结果再取反。这两个\"取反\"是必须的，否则和标准工具算出来的值不一致，联调时会以为代码错了。" },
      { type: "code", q: "任务一：实现 CRC32 模块（crc32.h / crc32.c）。要求：提供流式三件套 + 一次性计算接口；表在首次调用时惰性初始化且线程安全；并用 \"123456789\" 自测断言结果等于 0xCBF43926。",
        hint: "<p>多项式 0xEDB88320（反射形式）；流式接口必须是可重入的（状态由调用者持有，不要用全局变量存中间值）；线程安全可用 pthread_once 或静态初始化标记。</p>",
        sol: "/* crc32.h */\n#ifndef CRC32_H\n#define CRC32_H\n#include <stdint.h>\n#include <stddef.h>\n\nuint32_t crc32_begin(void);\nuint32_t crc32_update(uint32_t crc, const uint8_t *data, size_t len);\nuint32_t crc32_finish(uint32_t crc);\nuint32_t crc32_calc(const uint8_t *data, size_t len);\n\n#endif\n\n/* crc32.c */\n#include \"crc32.h\"\n#include <pthread.h>\n\nstatic uint32_t g_table[256];\nstatic pthread_once_t g_once = PTHREAD_ONCE_INIT;\n\nstatic void crc32_build_table(void)\n{\n    for (uint32_t i = 0; i < 256; i++) {\n        uint32_t c = i;\n        for (int k = 0; k < 8; k++)\n            c = (c & 1u) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);\n        g_table[i] = c;\n    }\n}\n\nuint32_t crc32_begin(void)\n{\n    pthread_once(&g_once, crc32_build_table);   /* 惰性且只建一次，线程安全 */\n    return 0xFFFFFFFFu;\n}\n\nuint32_t crc32_update(uint32_t crc, const uint8_t *data, size_t len)\n{\n    if (data == NULL) return crc;               /* 允许 len=0 的边界调用 */\n    for (size_t i = 0; i < len; i++)\n        crc = g_table[(crc ^ data[i]) & 0xFFu] ^ (crc >> 8);\n    return crc;\n}\n\nuint32_t crc32_finish(uint32_t crc)\n{\n    return crc ^ 0xFFFFFFFFu;\n}\n\nuint32_t crc32_calc(const uint8_t *data, size_t len)\n{\n    return crc32_finish(crc32_update(crc32_begin(), data, len));\n}\n\n/* 自测：标准向量 */\nint crc32_selftest(void)\n{\n    const char *v = \"123456789\";\n    uint32_t c = crc32_calc((const uint8_t *)v, 9);\n    if (c != 0xCBF43926u) {\n        printf(\"[CRC] selftest FAIL: 0x%08X (expect 0xCBF43926)\\n\", c);\n        return -1;\n    }\n    printf(\"[CRC] selftest OK\\n\");\n    return 0;\n}",
        exp: "三个细节：① 用 pthread_once 做惰性初始化（比\"启动时手动初始化\"更不容易忘，也天生线程安全）；② 流式接口把中间状态交给调用者持有，保证可重入；③ 自测向量是标准做法——查表算法一旦写错，是\"看起来能算但值不对\"，只有比对标准值才能发现。" },
      { type: "code", q: "任务二：实现打包函数 pack_update(input_path, output_path, version)。要求：读取固件文件 → 计算负载长度与 CRC → 写头部（含头 CRC）→ 写负载；输出用二进制模式；出错要清理半成品文件。",
        hint: "<p>头部结构用 #pragma pack(1) 或 __attribute__((packed)) 保证按字节紧凑排列；header_crc 用 offsetof 只算 header_crc 之前的字段；写文件前先 fopen(\"wb\")；失败时 remove(output_path)。</p>",
        sol: "#include <stddef.h>\n#include <stdio.h>\n#include <stdint.h>\n#include <string.h>\n\n#define FW_MAGIC 0x4F544150u          /* \"OTAP\" */\n#define FW_MAX_PAYLOAD (16u * 1024u * 1024u)\n\ntypedef struct __attribute__((packed)) {\n    uint32_t magic;\n    uint32_t version;\n    uint32_t payload_len;\n    uint32_t payload_crc;\n    uint32_t header_crc;              /* 前 20 字节的 CRC32 */\n} fw_header_t;\n\nint pack_update(const char *in_path, const char *out_path, uint32_t version)\n{\n    FILE *fi = fopen(in_path, \"rb\");\n    if (fi == NULL) { perror(\"open input\"); return -1; }\n\n    /* 取输入大小 */\n    fseek(fi, 0, SEEK_END);\n    long plen = ftell(fi);\n    rewind(fi);\n    if (plen <= 0 || (uint32_t)plen > FW_MAX_PAYLOAD) { fclose(fi); return -1; }\n\n    FILE *fo = fopen(out_path, \"wb\");\n    if (fo == NULL) { perror(\"open output\"); fclose(fi); return -1; }\n\n    /* 边读边算负载 CRC，同时写入负载 */\n    fw_header_t h;\n    memset(&h, 0, sizeof(h));\n    h.magic = FW_MAGIC;\n    h.version = version;\n    h.payload_len = (uint32_t)plen;\n\n    if (fseek(fo, sizeof(fw_header_t), SEEK_SET) != 0) goto fail;   /* 先占位 */\n\n    uint32_t crc = crc32_begin();\n    uint8_t buf[4096];\n    long left = plen;\n    while (left > 0) {\n        size_t n = fread(buf, 1, (left < (long)sizeof(buf)) ? (size_t)left : sizeof(buf), fi);\n        if (n == 0) goto fail;\n        crc = crc32_update(crc, buf, n);\n        if (fwrite(buf, 1, n, fo) != n) goto fail;\n        left -= (long)n;\n    }\n    h.payload_crc = crc32_finish(crc);\n\n    /* 计算头部 CRC（只覆盖 header_crc 之前的字段） */\n    h.header_crc = crc32_calc((const uint8_t *)&h, offsetof(fw_header_t, header_crc));\n\n    /* 回到文件头写头部 */\n    if (fseek(fo, 0, SEEK_SET) != 0) goto fail;\n    if (fwrite(&h, sizeof(h), 1, fo) != 1) goto fail;\n\n    fclose(fi);\n    fclose(fo);\n    printf(\"[PACK] ok: %s (payload=%ld, crc=0x%08X)\\n\", out_path, plen, h.payload_crc);\n    return 0;\n\nfail:\n    fclose(fi);\n    fclose(fo);\n    remove(out_path);                 /* 清理半成品，避免误刷 */\n    printf(\"[PACK] failed, output removed\\n\");\n    return -1;\n}",
        exp: "要点：① 十六进制 magic 用固定标识，能第一时间识别\"这不是我们的包\"；② 先占位写负载、最后回填头部（单文件内完成打包）；③ 任何一步失败都要 remove 半成品——半个升级包比没有包更危险；④ 大小上限校验，防止恶意/损坏的包头引发巨大内存分配。" },
      { type: "code", q: "任务三：实现 verify_update(path, &hdr)。要求逐项校验并返回不同的错误码：文件不存在 / 头读取失败 / magic 不对 / 头 CRC 不对 / 长度非法 / 文件大小与头不符 / 负载 CRC 不匹配。",
        hint: "<p>用流式 CRC 逐块校验负载，不要一次读进内存；文件实际大小 = 头大小 + payload_len 必须成立；每个失败分支都要 fclose。</p>",
        sol: "enum {\n    FW_OK            =  0,\n    FW_E_OPEN        = -1,\n    FW_E_HDR_READ    = -2,\n    FW_E_MAGIC       = -3,\n    FW_E_HDR_CRC     = -4,\n    FW_E_LEN         = -5,\n    FW_E_SIZE        = -6,\n    FW_E_PAYLOAD_CRC = -7\n};\n\nint verify_update(const char *path, fw_header_t *out_hdr)\n{\n    FILE *fp = fopen(path, \"rb\");\n    if (fp == NULL) return FW_E_OPEN;\n\n    fw_header_t h;\n    if (fread(&h, sizeof(h), 1, fp) != 1) { fclose(fp); return FW_E_HDR_READ; }\n\n    if (h.magic != FW_MAGIC) { fclose(fp); return FW_E_MAGIC; }\n\n    uint32_t hcrc = crc32_calc((const uint8_t *)&h, offsetof(fw_header_t, header_crc));\n    if (hcrc != h.header_crc) { fclose(fp); return FW_E_HDR_CRC; }\n\n    if (h.payload_len == 0 || h.payload_len > FW_MAX_PAYLOAD) { fclose(fp); return FW_E_LEN; }\n\n    fseek(fp, 0, SEEK_END);\n    long fsize = ftell(fp);\n    if (fsize != (long)(sizeof(fw_header_t) + h.payload_len)) { fclose(fp); return FW_E_SIZE; }\n\n    /* 逐块校验负载 CRC，内存占用恒定 */\n    if (fseek(fp, sizeof(fw_header_t), SEEK_SET) != 0) { fclose(fp); return FW_E_PAYLOAD_CRC; }\n    uint32_t crc = crc32_begin();\n    uint8_t buf[4096];\n    long left = (long)h.payload_len;\n    while (left > 0) {\n        size_t n = fread(buf, 1, (left < (long)sizeof(buf)) ? (size_t)left : sizeof(buf), fp);\n        if (n == 0) { fclose(fp); return FW_E_PAYLOAD_CRC; }\n        crc = crc32_update(crc, buf, n);\n        left -= (long)n;\n    }\n    if (crc32_finish(crc) != h.payload_crc) { fclose(fp); return FW_E_PAYLOAD_CRC; }\n\n    fclose(fp);\n    if (out_hdr) *out_hdr = h;\n    LOGI(\"ota\", \"verify ok: ver=%u len=%u\", h.version, h.payload_len);\n    return FW_OK;\n}",
        exp: "设计要点：① 校验顺序从便宜到昂贵（magic → 头 CRC → 长度 → 文件大小 → 负载 CRC），坏包尽早拒绝、少做无用计算；② 分块流式校验，内存占用恒定（16MB 固件也不会吃 16MB RAM）；③ 每个分支都释放资源——驱动/工具类代码最常见的泄漏来源。" },
      { type: "code", q: "任务四：实现 apply_update(pkg_path, target_path)。要求：先 verify；校验通过后把负载写入目标分区；写完<b>回读比对</b>；成功后写\"待确认\"标记并提示重启；任何失败都不能破坏目标分区原有内容。",
        hint: "<p>关键点：\"不能破坏原有内容\"意味着要写临时文件 + 成功后 rename 原子替换；回读比对用 CRC 而不是逐字节（更快更省代码）；标记文件写成简单文本或一字节即可。</p>",
        sol: "int apply_update(const char *pkg_path, const char *target_path)\n{\n    fw_header_t h;\n    int rc = verify_update(pkg_path, &h);\n    if (rc != FW_OK) {\n        LOGE(\"ota\", \"verify failed: %d\", rc);\n        return rc;                          /* 校验不通过，绝不碰目标分区 */\n    }\n\n    FILE *fi = fopen(pkg_path, \"rb\");\n    if (!fi) return FW_E_OPEN;\n\n    char tmp_path[320];\n    snprintf(tmp_path, sizeof(tmp_path), \"%s.tmp\", target_path);\n    FILE *fo = fopen(tmp_path, \"wb\");\n    if (!fo) { fclose(fi); return FW_E_OPEN; }\n\n    if (fseek(fi, sizeof(fw_header_t), SEEK_SET) != 0) { fclose(fi); fclose(fo); remove(tmp_path); return -1; }\n\n    uint32_t crc = crc32_begin();\n    uint8_t buf[4096];\n    long left = (long)h.payload_len;\n    while (left > 0) {\n        size_t n = fread(buf, 1, (left < (long)sizeof(buf)) ? (size_t)left : sizeof(buf), fi);\n        if (n == 0) goto fail;\n        crc = crc32_update(crc, buf, n);\n        if (fwrite(buf, 1, n, fo) != n) goto fail;\n        left -= (long)n;\n    }\n    if (fwrite_buffered(fo) != 0) goto fail;      /* fflush + fsync：确保真正落盘 */\n\n    /* 回读比对：确认写进去的和预期一致 */\n    if (crc32_file(tmp_path) != h.payload_crc) {\n        LOGE(\"ota\", \"verify after write failed\");\n        goto fail;\n    }\n\n    fclose(fi);\n    fclose(fo);\n    fi = fo = NULL;\n\n    /* 原子替换：只有到这里才覆盖目标分区 */\n    if (rename(tmp_path, target_path) != 0) {\n        LOGE(\"ota\", \"rename failed\");\n        remove(tmp_path);\n        return -1;\n    }\n\n    /* 写待确认标记：新固件启动成功后必须清掉，否则 bootloader 回滚 */\n    write_marker(MARK_PENDING_CONFIRM, h.version);\n    LOGI(\"ota\", \"update applied, ver=%u, please reboot\", h.version);\n    return FW_OK;\n\nfail:\n    if (fi) fclose(fi);\n    if (fo) fclose(fo);\n    remove(tmp_path);                        /* 目标分区保持原样 */\n    LOGE(\"ota\", \"apply failed, original untouched\");\n    return -1;\n}",
        exp: "这是可靠升级的核心：① <b>先写临时文件、回读校验、最后 rename 原子替换</b>——保证\"要么全新固件、要么完全没变\"，绝不会出现刷了一半的砖；② 落盘要 fsync，否则掉电时写入可能还在缓存里；③ 待确认标记配合 bootloader 实现\"启动失败自动回滚\"。能讲清这套流程，面试官会认为你真做过产品级固件。" }
    ]
  }
  ]
});


